        return {
            'Name': label.name,
            'Confidence': label.confidence,
            'Instances': label.instances,
            'Parents': label.parents
        }

    @staticmethod
    def _moderation_label_to_dict(label):
        return {
            'Name': label.name,
            'Confidence': label.confidence,
            'ParentName': label.parent_name
